-- SOURCE CANDIDATE: same private source authority, server-selected active scope.
-- No claim, model, financial download, caller source/clock or quota allocation.
BEGIN ISOLATION LEVEL READ COMMITTED;
SET LOCAL statement_timeout='30s';SET LOCAL lock_timeout='2s';
SELECT pg_advisory_xact_lock(64221022);
DO $pre$
DECLARE before_namespace jsonb;catalog_sql constant text:=$catalog$
 SELECT jsonb_build_object(
  'namespace',(SELECT to_jsonb(n) FROM pg_namespace n WHERE n.oid='public'::regnamespace),
  'routines',(SELECT coalesce(jsonb_agg(CASE WHEN p.oid=ANY($1) THEN to_jsonb(p)-'prosrc' ELSE to_jsonb(p) END ORDER BY p.oid),'[]'::jsonb) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND NOT(p.oid=ANY($2))),
  'relations',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_class c WHERE c.relnamespace='public'::regnamespace),
  'columns',(SELECT coalesce(jsonb_agg(CASE WHEN EXISTS(SELECT FROM jsonb_each($3) edge WHERE a.attrelid=to_regclass('public.'||edge.key) AND edge.value ? a.attname) THEN to_jsonb(a)-'attacl' ELSE to_jsonb(a) END ORDER BY a.attrelid,a.attnum),'[]'::jsonb) FROM pg_attribute a WHERE a.attrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'types',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]'::jsonb) FROM pg_type t WHERE t.typnamespace='public'::regnamespace),
  'constraints',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_constraint c WHERE c.connamespace='public'::regnamespace),
  'defaults',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.oid),'[]'::jsonb) FROM pg_attrdef d WHERE d.adrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'indexes',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.indexrelid),'[]'::jsonb) FROM pg_index i WHERE i.indrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.oid),'[]'::jsonb) FROM pg_policy p WHERE p.polrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace) AND NOT(p.polname='vnext_target_read_v1' AND EXISTS(SELECT FROM jsonb_each($3) edge WHERE p.polrelid=to_regclass('public.'||edge.key)))),
  'triggers',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]'::jsonb) FROM pg_trigger t WHERE t.tgrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'rules',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.oid),'[]'::jsonb) FROM pg_rewrite r WHERE r.ev_class IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'operators',(SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY o.oid),'[]'::jsonb) FROM pg_operator o WHERE o.oprnamespace='public'::regnamespace),
  'collations',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_collation c WHERE c.collnamespace='public'::regnamespace),
  'defaultAcls',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.oid),'[]'::jsonb) FROM pg_default_acl a WHERE a.defaclnamespace IN(0,'public'::regnamespace)),
  'roleSettings',(SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.setdatabase,s.setrole),'[]'::jsonb) FROM pg_db_role_setting s),'roles',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.rolname) FROM pg_roles r),
  'memberships',(SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.roleid,m.member),'[]'::jsonb) FROM pg_auth_members m))
 $catalog$;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' OR EXISTS(SELECT FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='vnext_forecast_active_read_v1') THEN RAISE EXCEPTION 'vnext_forecast_active_first_install_required';END IF;
 IF NOT EXISTS(SELECT FROM pg_roles r WHERE r.rolname='stockinsider_vnext_owner' AND NOT r.rolcanlogin AND NOT r.rolsuper AND NOT r.rolcreatedb AND NOT r.rolcreaterole AND NOT r.rolreplication AND NOT r.rolbypassrls AND r.rolconfig IS NULL) OR EXISTS(SELECT FROM pg_auth_members WHERE roleid='stockinsider_vnext_owner'::regrole OR member='stockinsider_vnext_owner'::regrole) OR EXISTS(SELECT FROM pg_db_role_setting WHERE setrole='stockinsider_vnext_owner'::regrole) THEN RAISE EXCEPTION 'vnext_forecast_active_owner';END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p WHERE p.oid=to_regprocedure('public.vnext_forecast_rights_guard_v1()') AND pg_get_userbyid(p.proowner)='opportunity_v3_rpc_owner' AND p.prosecdef=false AND p.provolatile='v' AND p.prokind='f' AND p.prorettype='trigger'::regtype AND p.proconfig=ARRAY['search_path=pg_catalog, public'] AND (SELECT lanname FROM pg_language WHERE oid=p.prolang)='plpgsql' AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='6d90196a6ccaf0fdbc296ad196ae8c2525a7cd9febc504a5431d8d3322f4e414') THEN RAISE EXCEPTION 'vnext_forecast_active_dependency';END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p WHERE p.oid=to_regprocedure('public.vnext_forecast_stock_id_internal_v1(text)') AND pg_get_userbyid(p.proowner)='stockinsider_vnext_owner' AND p.prosecdef=true AND p.provolatile='s' AND p.prokind='f' AND p.prorettype='uuid'::regtype AND p.proconfig=ARRAY['search_path=pg_catalog, public','statement_timeout=30s','lock_timeout=2s'] AND (SELECT lanname FROM pg_language WHERE oid=p.prolang)='plpgsql' AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='d1508916a64a8e9414dad908c730da4f7abaeb9b1e83920b7143ac6bf6283f26') THEN RAISE EXCEPTION 'vnext_forecast_active_dependency';END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p WHERE p.oid=to_regprocedure('public.vnext_forecast_current_internal_v1(uuid,text,timestamp with time zone)') AND pg_get_userbyid(p.proowner)='opportunity_v3_rpc_owner' AND p.prosecdef=true AND p.provolatile='s' AND p.prokind='f' AND p.prorettype='jsonb'::regtype AND p.proconfig=ARRAY['search_path=pg_catalog, public','statement_timeout=30s','lock_timeout=2s'] AND (SELECT lanname FROM pg_language WHERE oid=p.prolang)='plpgsql' AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='507f6e7ffb24af6cc6a4dbd34090b79065ae566fdb3831b9a0fa3e0588268016') THEN RAISE EXCEPTION 'vnext_forecast_active_dependency';END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p WHERE p.oid=to_regprocedure('public.vnext_forecast_evidence_current_internal_v1(jsonb,text)') AND pg_get_userbyid(p.proowner)='stockinsider_vnext_owner' AND p.prosecdef=true AND p.provolatile='s' AND p.prokind='f' AND p.prorettype='boolean'::regtype AND p.proconfig=ARRAY['search_path=pg_catalog, public','statement_timeout=30s','lock_timeout=2s'] AND (SELECT lanname FROM pg_language WHERE oid=p.prolang)='plpgsql' AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='56ceca2c904e3e00c08f424ae52cd23bc0b08e5c5a6adb4af0de8e7d4c493d5b') THEN RAISE EXCEPTION 'vnext_forecast_active_dependency';END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p WHERE p.oid=to_regprocedure('public.vnext_forecast_read_v1(text,uuid,uuid)') AND pg_get_userbyid(p.proowner)='stockinsider_vnext_owner' AND p.prosecdef=true AND p.provolatile='v' AND p.prokind='f' AND p.prorettype='jsonb'::regtype AND p.proconfig=ARRAY['search_path=pg_catalog, public','statement_timeout=30s','lock_timeout=2s'] AND (SELECT lanname FROM pg_language WHERE oid=p.prolang)='plpgsql' AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='45ba04f9632a3b5f11883326f59dce072eea2a3a7c1d49ecb4d390e8947295a8') THEN RAISE EXCEPTION 'vnext_forecast_active_dependency';END IF;
 IF NOT EXISTS(SELECT FROM pg_proc p WHERE p.oid=to_regprocedure('public.vnext_forecast_input_current_internal_v1(jsonb,text)') AND pg_get_userbyid(p.proowner)='stockinsider_vnext_owner' AND p.prosecdef=true AND p.provolatile='s' AND p.prokind='f' AND p.prorettype='boolean'::regtype AND p.proconfig=ARRAY['search_path=pg_catalog, public','statement_timeout=30s','lock_timeout=2s'] AND (SELECT lanname FROM pg_language WHERE oid=p.prolang)='plpgsql' AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='73259367f3d9383e09d704bf226b0d4856cd04ea7362f44aae978a8770584f00') THEN RAISE EXCEPTION 'vnext_forecast_active_dependency';END IF;
 IF (SELECT count(*) FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.pronamespace='public'::regnamespace AND p.proname='vnext_forecast_stock_id_internal_v1')<>1 OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.pronamespace='public'::regnamespace AND p.proname='vnext_forecast_stock_id_internal_v1' AND (a.grantor<>p.proowner OR a.grantee NOT IN('stockinsider_vnext_owner'::regrole) OR a.privilege_type<>'EXECUTE' OR a.is_grantable)) THEN RAISE EXCEPTION 'vnext_forecast_active_dependency_acl';END IF;
 IF (SELECT count(*) FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.pronamespace='public'::regnamespace AND p.proname='vnext_forecast_rights_guard_v1')<>1 OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.pronamespace='public'::regnamespace AND p.proname='vnext_forecast_rights_guard_v1' AND (a.grantor<>p.proowner OR a.grantee NOT IN('opportunity_v3_rpc_owner'::regrole) OR a.privilege_type<>'EXECUTE' OR a.is_grantable)) THEN RAISE EXCEPTION 'vnext_forecast_active_dependency_acl';END IF;
 IF (SELECT count(*) FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.pronamespace='public'::regnamespace AND p.proname='vnext_forecast_current_internal_v1')<>2 OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.pronamespace='public'::regnamespace AND p.proname='vnext_forecast_current_internal_v1' AND (a.grantor<>p.proowner OR a.grantee NOT IN('opportunity_v3_rpc_owner'::regrole,'stockinsider_vnext_owner'::regrole) OR a.privilege_type<>'EXECUTE' OR a.is_grantable)) THEN RAISE EXCEPTION 'vnext_forecast_active_dependency_acl';END IF;
 IF (SELECT count(*) FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.pronamespace='public'::regnamespace AND p.proname='vnext_forecast_evidence_current_internal_v1')<>1 OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.pronamespace='public'::regnamespace AND p.proname='vnext_forecast_evidence_current_internal_v1' AND (a.grantor<>p.proowner OR a.grantee NOT IN('stockinsider_vnext_owner'::regrole) OR a.privilege_type<>'EXECUTE' OR a.is_grantable)) THEN RAISE EXCEPTION 'vnext_forecast_active_dependency_acl';END IF;
 IF (SELECT count(*) FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.pronamespace='public'::regnamespace AND p.proname='vnext_forecast_input_current_internal_v1')<>1 OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.pronamespace='public'::regnamespace AND p.proname='vnext_forecast_input_current_internal_v1' AND (a.grantor<>p.proowner OR a.grantee NOT IN('stockinsider_vnext_owner'::regrole) OR a.privilege_type<>'EXECUTE' OR a.is_grantable)) THEN RAISE EXCEPTION 'vnext_forecast_active_dependency_acl';END IF;
 IF (SELECT count(*) FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.pronamespace='public'::regnamespace AND p.proname='vnext_forecast_read_v1')<>2 OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.pronamespace='public'::regnamespace AND p.proname='vnext_forecast_read_v1' AND (a.grantor<>p.proowner OR a.grantee NOT IN('stockinsider_vnext_owner'::regrole,'service_role'::regrole) OR a.privilege_type<>'EXECUTE' OR a.is_grantable)) THEN RAISE EXCEPTION 'vnext_forecast_active_dependency_acl';END IF;
 EXECUTE catalog_sql INTO before_namespace USING ARRAY[]::oid[],ARRAY[]::oid[],'{}'::jsonb;
 PERFORM set_config('vnext.forecast_active_before',before_namespace::text,true);
END $pre$;
CREATE FUNCTION public.vnext_forecast_active_read_v1(p_principal text) RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=pg_catalog,public SET statement_timeout='30s' SET lock_timeout='2s' AS $active$
DECLARE member record;stock uuid;members jsonb:='[]'::jsonb;result jsonb;amount integer:=0;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN RAISE EXCEPTION 'vnext_read_committed_required';END IF;
 PERFORM pg_advisory_xact_lock(64221022);
 IF NOT EXISTS(SELECT FROM public.vnext_mode_v1 WHERE enabled AND legacy_fenced) OR NOT EXISTS(SELECT FROM public.vnext_principals_v1 WHERE principal=p_principal AND enabled AND role='operator') THEN RAISE EXCEPTION 'vnext_forecast_operator_mode_required';END IF;
 FOR member IN SELECT symbol,input_hash FROM public.vnext_members_v1 WHERE state<>'exited' ORDER BY symbol LIMIT 21 LOOP
  amount:=amount+1;IF amount>20 THEN RAISE EXCEPTION 'vnext_forecast_active_bound';END IF;
  stock:=public.vnext_forecast_stock_id_internal_v1(member.symbol);
  members:=members||jsonb_build_array(jsonb_build_object('symbol',member.symbol,'inputHash',member.input_hash,'forecast',public.vnext_forecast_current_internal_v1(stock,member.symbol,statement_timestamp())));
 END LOOP;
 result:=jsonb_build_object('schemaVersion','vnext-active-forecasts-v1','asOf',statement_timestamp(),'members',members);
 IF octet_length(convert_to(result::text,'UTF8'))>1048576 THEN RAISE EXCEPTION 'vnext_forecast_active_bytes';END IF;
 RETURN result;
END $active$;
ALTER FUNCTION public.vnext_forecast_active_read_v1(text) OWNER TO stockinsider_vnext_owner;
REVOKE ALL ON FUNCTION public.vnext_forecast_active_read_v1(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.vnext_forecast_active_read_v1(text) TO service_role;
DO $post$
DECLARE target oid:='public.vnext_forecast_active_read_v1(text)'::regprocedure;after_namespace jsonb;catalog_sql constant text:=$catalog$
 SELECT jsonb_build_object(
  'namespace',(SELECT to_jsonb(n) FROM pg_namespace n WHERE n.oid='public'::regnamespace),
  'routines',(SELECT coalesce(jsonb_agg(CASE WHEN p.oid=ANY($1) THEN to_jsonb(p)-'prosrc' ELSE to_jsonb(p) END ORDER BY p.oid),'[]'::jsonb) FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND NOT(p.oid=ANY($2))),
  'relations',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_class c WHERE c.relnamespace='public'::regnamespace),
  'columns',(SELECT coalesce(jsonb_agg(CASE WHEN EXISTS(SELECT FROM jsonb_each($3) edge WHERE a.attrelid=to_regclass('public.'||edge.key) AND edge.value ? a.attname) THEN to_jsonb(a)-'attacl' ELSE to_jsonb(a) END ORDER BY a.attrelid,a.attnum),'[]'::jsonb) FROM pg_attribute a WHERE a.attrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'types',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]'::jsonb) FROM pg_type t WHERE t.typnamespace='public'::regnamespace),
  'constraints',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_constraint c WHERE c.connamespace='public'::regnamespace),
  'defaults',(SELECT coalesce(jsonb_agg(to_jsonb(d) ORDER BY d.oid),'[]'::jsonb) FROM pg_attrdef d WHERE d.adrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'indexes',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY i.indexrelid),'[]'::jsonb) FROM pg_index i WHERE i.indrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.oid),'[]'::jsonb) FROM pg_policy p WHERE p.polrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace) AND NOT(p.polname='vnext_target_read_v1' AND EXISTS(SELECT FROM jsonb_each($3) edge WHERE p.polrelid=to_regclass('public.'||edge.key)))),
  'triggers',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY t.oid),'[]'::jsonb) FROM pg_trigger t WHERE t.tgrelid IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'rules',(SELECT coalesce(jsonb_agg(to_jsonb(r) ORDER BY r.oid),'[]'::jsonb) FROM pg_rewrite r WHERE r.ev_class IN(SELECT oid FROM pg_class WHERE relnamespace='public'::regnamespace)),
  'operators',(SELECT coalesce(jsonb_agg(to_jsonb(o) ORDER BY o.oid),'[]'::jsonb) FROM pg_operator o WHERE o.oprnamespace='public'::regnamespace),
  'collations',(SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.oid),'[]'::jsonb) FROM pg_collation c WHERE c.collnamespace='public'::regnamespace),
  'defaultAcls',(SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.oid),'[]'::jsonb) FROM pg_default_acl a WHERE a.defaclnamespace IN(0,'public'::regnamespace)),
  'roleSettings',(SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.setdatabase,s.setrole),'[]'::jsonb) FROM pg_db_role_setting s),'roles',(SELECT jsonb_agg(to_jsonb(r) ORDER BY r.rolname) FROM pg_roles r),
  'memberships',(SELECT coalesce(jsonb_agg(to_jsonb(m) ORDER BY m.roleid,m.member),'[]'::jsonb) FROM pg_auth_members m))
 $catalog$;
BEGIN
 IF NOT EXISTS(SELECT FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=target AND pg_get_userbyid(p.proowner)='stockinsider_vnext_owner' AND l.lanname='plpgsql' AND p.prokind='f' AND p.prorettype='jsonb'::regtype AND NOT p.proretset AND p.pronargs=1 AND p.proargtypes='25'::oidvector AND p.proargnames=ARRAY['p_principal'] AND p.proallargtypes IS NULL AND p.proargmodes IS NULL AND p.provariadic=0 AND p.pronargdefaults=0 AND p.proargdefaults IS NULL AND p.provolatile='v' AND p.proparallel='u' AND NOT p.proisstrict AND NOT p.proleakproof AND p.prosecdef AND p.proconfig=ARRAY['search_path=pg_catalog, public','statement_timeout=30s','lock_timeout=2s'] AND p.procost=100 AND p.prorows=0 AND p.probin IS NULL AND p.prosqlbody IS NULL AND encode(sha256(convert_to(p.prosrc,'UTF8')),'hex')='00e8e39e8743300212ca9212a412d4bf22b62d9597a403c5209f78f02f4aa0c4') THEN RAISE EXCEPTION 'vnext_forecast_active_profile';END IF;
 IF (SELECT count(*) FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=target)<>2 OR EXISTS(SELECT FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=target AND (a.grantor<>p.proowner OR a.grantee NOT IN(p.proowner,'service_role'::regrole) OR a.privilege_type<>'EXECUTE' OR a.is_grantable)) THEN RAISE EXCEPTION 'vnext_forecast_active_acl';END IF;
 EXECUTE catalog_sql INTO after_namespace USING ARRAY[]::oid[],ARRAY[target],'{}'::jsonb;
 IF after_namespace IS DISTINCT FROM current_setting('vnext.forecast_active_before')::jsonb THEN RAISE EXCEPTION 'vnext_forecast_active_namespace';END IF;
END $post$;
COMMIT;
